param([string]$ExePath="C:\Users\everg\routerfarm-release\dist\win-unpacked\RouterFarm.exe",[string]$ServerScript="C:\Users\everg\routerfarm-release\server.js",[string]$StatusUrl="http://127.0.0.1:7781/api/status",[int]$PollSeconds=20,[string]$LogPath="C:\Users\everg\routerfarm-release\logs\watch-routerfarm.log")
function Write-WatchLog([string]$m){$t=Get-Date -Format "yyyy-MM-dd HH:mm:ss";"[$t] $m"|Add-Content -Path $LogPath}
while($true){try{$h=$false;try{$r=Invoke-RestMethod -Uri $StatusUrl -TimeoutSec 5;$h=[bool]$r.ok}catch{$h=$false};if(-not $h){Write-WatchLog "Server down. Restarting...";Get-Process node -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like "*server.js*"}|Stop-Process -Force -ErrorAction SilentlyContinue;Start-Process "node.exe" -ArgumentList $ServerScript -WorkingDirectory (Split-Path $ServerScript) -WindowStyle Hidden;Start-Sleep -Seconds 10};if(-not (Get-Process RouterFarm -ErrorAction SilentlyContinue)){Write-WatchLog "App down. Restarting...";Start-Process $ExePath -WorkingDirectory (Split-Path (Split-Path $ExePath))}}catch{Write-WatchLog "Error: $($_.Exception.Message)"};Start-Sleep -Seconds $PollSeconds}
